    internal class JurorElementConverter : JsonConverter
    {
        public override bool CanConvert(Type t) => t == typeof(JurorElement) || t == typeof(JurorElement?);

        public override object ReadJson(JsonReader reader, Type t, object existingValue, JsonSerializer serializer)
        {
            switch (reader.TokenType)
            {
                case JsonToken.Boolean:
                    var boolValue = serializer.Deserialize<bool>(reader);
                    return new JurorElement { Bool = boolValue };
                case JsonToken.StartObject:
                    var objectValue = serializer.Deserialize<JurorClass>(reader);
                    return new JurorElement { JurorClass = objectValue };
            }
            throw new Exception("Cannot unmarshal type JurorElement");
        }

        public override void WriteJson(JsonWriter writer, object untypedValue, JsonSerializer serializer)
        {
            var value = (JurorElement)untypedValue;
            if (value.Bool != null)
            {
                serializer.Serialize(writer, value.Bool.Value);
                return;
            }
            if (value.JurorClass != null)
            {
                serializer.Serialize(writer, value.JurorClass);
                return;
            }
            throw new Exception("Cannot marshal type JurorElement");
        }

        public static readonly JurorElementConverter Singleton = new JurorElementConverter();
    }

